-- free-exercise-db import (https://github.com/yuhonas/free-exercise-db, Unlicense / public domain).
-- Generated by scripts/exercise-import/convert.mjs. Data only; safe to run more than once.
-- Existing rows are never changed: conflicts on slug are ignored, and any exercise whose name already exists
-- (ignoring case and punctuation) is skipped.
-- Part 4 of 6.

INSERT INTO public.exercises (slug, name, family, equipment, muscle_group, primary_muscles, secondary_muscles, steps)
SELECT v.slug, v.name, v.family, v.equipment, v.muscle_group, v.primary_muscles, v.secondary_muscles, v.steps
FROM (VALUES
('middle-back-shrug','Middle Back Shrug','shrug','dumbbell','back',ARRAY['upper-back']::text[],ARRAY[]::text[],ARRAY['Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.','As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.','As you inhale go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
('middle-back-stretch','Middle Back Stretch','stretch','other','back',ARRAY['upper-back']::text[],ARRAY['abs','lats','lower-back']::text[],ARRAY['Stand so your feet are shoulder width apart and your hands are on your hips.','Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.']::text[]),
('mixed-grip-chin','Mixed Grip Chin','mixed-chin','other','back',ARRAY['upper-back']::text[],ARRAY['biceps','lats']::text[],ARRAY['Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.','Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.','After a second contraction at the top, start to slowly come down as you inhale.','Repeat for the recommended amount of repetitions.','On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left.']::text[]),
('monster-walk','Monster Walk','monster-walk','other','legs',ARRAY['glutes']::text[],ARRAY[]::text[],ARRAY['Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.','To begin, take short steps forward alternating your left and right foot.','After several steps, do just the opposite and walk backward to where you started.']::text[]),
('mountain-climbers','Mountain Climbers','mountain-climbers','other','legs',ARRAY['quads']::text[],ARRAY['chest','hamstrings','shoulders-front','shoulders-side']::text[],ARRAY['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.','Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.']::text[]),
('moving-claw-series','Moving Claw Series','moving-claw-series','other','legs',ARRAY['hamstrings']::text[],ARRAY['calves','quads']::text[],ARRAY['This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.','Reload the quad as the leg moves back forward, attacking the ground on the next step.','Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.']::text[]),
('muscle-snatch','Muscle Snatch','olympic-lift','barbell','legs',ARRAY['hamstrings']::text[],ARRAY['glutes','lower-back','quads','shoulders-front','shoulders-side','triceps']::text[],ARRAY['Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.','Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.','Continue raising the bar to the overhead position, without rebending the knees.']::text[]),
('muscle-up','Muscle Up','muscle-up','other','back',ARRAY['lats']::text[],ARRAY['abs','biceps','forearms','upper-back','shoulders-front','shoulders-side','traps','triceps']::text[],ARRAY['Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.','As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.','Maintaining control and stability, extend through the elbow to complete the motion.','Use care when lowering yourself to the ground.']::text[]),
('narrow-stance-hack-squats','Narrow Stance Hack Squats','squat','machine','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings']::text[],ARRAY['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.','Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.','Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).','Now straighten your legs without locking the knees. This will be your starting position.','Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.','Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
('narrow-stance-leg-press','Narrow Stance Leg Press','squat','machine','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings']::text[],ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.','Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[]),
('narrow-stance-squats','Narrow Stance Squats','squat','barbell','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings','lower-back']::text[],ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
('natural-glute-ham-raise','Natural Glute Ham Raise','natural-glute-ham','bodyweight','legs',ARRAY['hamstrings']::text[],ARRAY['calves','glutes','lower-back']::text[],ARRAY['Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.','This will be your starting position. Lower yourself under control until your knees are almost completely straight.','Remaining in control, raise yourself back up to the starting position.','If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.']::text[]),
('neck-smr','Neck-SMR','stretch','other','shoulders',ARRAY[]::text[],ARRAY[]::text[],ARRAY['Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.','Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.']::text[]),
('neck-press','Neck Press','neck-press','barbell','chest',ARRAY['chest']::text[],ARRAY['shoulders-front','shoulders-side','triceps']::text[],ARRAY['Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your neck.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
('oblique-crunches','Oblique Crunches','crunch','bodyweight','core',ARRAY['abs']::text[],ARRAY[]::text[],ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.','Make sure your feet are elevated and resting on a flat surface.','Now lift the shoulder in which your hand is touching your head.','Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.','After your knee touches your elbow, lower your body until you have reached the starting position.','Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.','Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[]),
('oblique-crunches-on-the-floor','Oblique Crunches - On The Floor','crunch','bodyweight','core',ARRAY['abs']::text[],ARRAY[]::text[],ARRAY['Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.','Place your left hand behind your head.','Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.','Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.','Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise.']::text[]),
('olympic-squat','Olympic Squat','squat','barbell','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings']::text[],ARRAY['Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.','Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.','At the moment the upper legs contact the lower, reverse the motion, driving the weight upward.']::text[]),
('on-your-back-quad-stretch','On-Your-Back Quad Stretch','stretch','other','legs',ARRAY['quads']::text[],ARRAY[]::text[],ARRAY['Lie on a flat bench or step, and hang one leg and arm over the side.','Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.','Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling.','Switch sides.']::text[]),
('on-your-side-quad-stretch','On Your Side Quad Stretch','stretch','other','legs',ARRAY['quads']::text[],ARRAY[]::text[],ARRAY['Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).','Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.']::text[]),
('one-arm-flat-bench-dumbbell-flye','One-Arm Flat Bench Dumbbell Flye','fly','dumbbell','chest',ARRAY['chest']::text[],ARRAY[]::text[],ARRAY['Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.','By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.','Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.','Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
('one-arm-high-pulley-cable-side-bends','One-Arm High-Pulley Cable Side Bends','pulley-side-bends','cable','core',ARRAY['abs']::text[],ARRAY[]::text[],ARRAY['Connect a standard handle to a tower. Move cable to highest pulley position.','Stand with side to cable. With one hand, reach up and grab handle with underhand grip.','Pull down cable until elbow touches your side and the handle is by your shoulder.','Position feet hip-width apart. Place free hand on hip to help gauge pivot point.','Keep arm in static position. Contract oblique to bring the weight down in a side crunch.','Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
('one-arm-incline-lateral-raise','One-Arm Incline Lateral Raise','lateral-raise','dumbbell','shoulders',ARRAY['shoulders-side']::text[],ARRAY[]::text[],ARRAY['Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.','Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.','While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.','While inhaling lower the weight across your body back into the starting position.','Repeat the movement for the prescribed amount of repetitions.','Switch arms and repeat the movement.']::text[]),
('one-arm-kettlebell-clean','One-Arm Kettlebell Clean','olympic-lift','other','legs',ARRAY['hamstrings']::text[],ARRAY['glutes','lower-back','shoulders-front','shoulders-side','traps']::text[],ARRAY['Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.','Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.','Return the weight to the starting position.']::text[]),
('one-arm-kettlebell-clean-and-jerk','One-Arm Kettlebell Clean and Jerk','olympic-lift','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY[]::text[],ARRAY['Hold a kettlebell by the handle.','Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.','Receive the weight overhead by returning to a squat position underneath the weight.','Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition.']::text[]),
('one-arm-kettlebell-floor-press','One-Arm Kettlebell Floor Press','flat-press','other','chest',ARRAY['chest']::text[],ARRAY['triceps']::text[],ARRAY['Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.','Press the kettlebell straight up toward the ceiling, rotating your wrist.','Lower the kettlebell back to the starting position and repeat.']::text[]),
('one-arm-kettlebell-jerk','One-Arm Kettlebell Jerk','olympic-lift','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['calves','quads','triceps']::text[],ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.','Lower the weight to perform the next repetition.']::text[]),
('one-arm-kettlebell-military-press-to-the-side','One-Arm Kettlebell Military Press To The Side','shoulder-press','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['triceps']::text[],ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.','Look at the kettlebell and press it up and out until it is locked out overhead.','Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[]),
('one-arm-kettlebell-para-press','One-Arm Kettlebell Para Press','para-press','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['triceps']::text[],ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.','Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[]),
('one-arm-kettlebell-push-press','One-Arm Kettlebell Push Press','shoulder-press','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['calves','quads','triceps']::text[],ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Lower the weight to perform the next repetition.']::text[]),
('one-arm-kettlebell-row','One-Arm Kettlebell Row','row','other','back',ARRAY['upper-back']::text[],ARRAY['biceps','lats']::text[],ARRAY['Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.']::text[]),
('one-arm-kettlebell-snatch','One-Arm Kettlebell Snatch','olympic-lift','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['calves','glutes','hamstrings','lower-back','traps','triceps']::text[],ARRAY['Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.','Look straight ahead and swing the kettlebell back between your legs.','Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.']::text[]),
('one-arm-kettlebell-split-jerk','One-Arm Kettlebell Split Jerk','olympic-lift','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['glutes','hamstrings','quads','triceps']::text[],ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.','Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.','Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.']::text[]),
('one-arm-kettlebell-split-snatch','One-Arm Kettlebell Split Snatch','olympic-lift','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['hamstrings','quads']::text[],ARRAY['Hold a kettlebell in one hand by the handle.','Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.','After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.','Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.']::text[]),
('one-arm-kettlebell-swings','One-Arm Kettlebell Swings','swings','other','legs',ARRAY['hamstrings']::text[],ARRAY['calves','glutes','lower-back','shoulders-front','shoulders-side']::text[],ARRAY[]::text[]),
('one-arm-long-bar-row','One-Arm Long Bar Row','row','barbell','back',ARRAY['upper-back']::text[],ARRAY['biceps','lats']::text[],ARRAY['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.','Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.','Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.','Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.','After a brief pause, return to the starting position.']::text[]),
('one-arm-medicine-ball-slam','One-Arm Medicine Ball Slam','medicine-slam','other','core',ARRAY['abs']::text[],ARRAY['lats','shoulders-front','shoulders-side']::text[],ARRAY['Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.','Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.','At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.','Catch the ball on the bounce and continue for the desired number of repetitions.']::text[]),
('one-arm-open-palm-kettlebell-clean','One-Arm Open Palm Kettlebell Clean','olympic-lift','other','legs',ARRAY['hamstrings']::text[],ARRAY['forearms','glutes','lower-back','quads','shoulders-front','shoulders-side']::text[],ARRAY['Place one kettlebell between your feet.','Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.','Throw the kettlebell out in front of you and catch the handle with one hand.','Take the kettlebell to the floor and repeat. Make sure to work both arms.']::text[]),
('one-arm-overhead-kettlebell-squats','One-Arm Overhead Kettlebell Squats','squat','other','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings','shoulders-front','shoulders-side']::text[],ARRAY['Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.','Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.','Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet.']::text[]),
('one-arm-side-deadlift','One-Arm Side Deadlift','deadlift','barbell','legs',ARRAY['quads']::text[],ARRAY['abs','calves','glutes','hamstrings','lower-back','traps']::text[],ARRAY['Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.','Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position.','Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position.','Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.','Repeat for the recommended amount of repetitions.','Switch arms and repeat the movement.']::text[]),
('one-arm-side-laterals','One-Arm Side Laterals','side-laterals','dumbbell','shoulders',ARRAY['shoulders-side']::text[],ARRAY[]::text[],ARRAY['Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.','Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','Lower the dumbbell back down slowly to the starting position as you inhale.','Repeat for the recommended amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
('one-legged-cable-kickback','One-Legged Cable Kickback','triceps','cable','legs',ARRAY['glutes']::text[],ARRAY['hamstrings']::text[],ARRAY['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.','Face the weight stack from a distance of about two feet, grasping the steel frame for support.','While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.','Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.','Repeat for the recommended amount of repetitions.','Switch legs and repeat the movement for the other side.']::text[]),
('one-arm-against-wall','One Arm Against Wall','stretch','other','back',ARRAY['lats']::text[],ARRAY[]::text[],ARRAY['From a standing position, place a bent arm against a wall or doorway.','Slowly lean toward your arm until you feel a stretch in your lats.']::text[]),
('one-arm-chin-up','One Arm Chin-Up','vertical-pull','other','back',ARRAY['upper-back']::text[],ARRAY['biceps','forearms','lats']::text[],ARRAY['For this exercise, start out by placing a towel around a chin up bar.','Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.','Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v','Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','Repeat this motion for the prescribed amount of repetitions.','Switch arms and repeat the movement.']::text[]),
('one-arm-dumbbell-bench-press','One Arm Dumbbell Bench Press','flat-press','dumbbell','chest',ARRAY['chest']::text[],ARRAY['shoulders-front','shoulders-side','triceps']::text[],ARRAY['Lie down on a flat bench with a dumbbell in one hand on top of your thigh.','By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.','Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.','Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions of your training program.','Switch arms and repeat the movement.']::text[]),
('one-arm-dumbbell-preacher-curl','One Arm Dumbbell Preacher Curl','curl','dumbbell','arms',ARRAY['biceps']::text[],ARRAY[]::text[],ARRAY['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.','As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.','Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.','Switch arms and repeat the movement.']::text[]),
('one-arm-floor-press','One Arm Floor Press','flat-press','barbell','arms',ARRAY['triceps']::text[],ARRAY['chest','shoulders-front','shoulders-side']::text[],ARRAY['Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.','Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).','Make sure the hand you are not using to lift the weight is placed by your side.','Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).','Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).','Repeat until you have performed your recommended repetitions.','Switch arms and repeat the movement.']::text[]),
('one-arm-lat-pulldown','One Arm Lat Pulldown','vertical-pull','cable','back',ARRAY['lats']::text[],ARRAY['biceps','upper-back']::text[],ARRAY['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.','Pull the handle down, squeezing your elbow to your side as you flex the elbow.','Pause at the bottom of the motion, and then slowly return the handle to the starting position.','For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.']::text[]),
('one-arm-pronated-dumbbell-triceps-extension','One Arm Pronated Dumbbell Triceps Extension','triceps','dumbbell','arms',ARRAY['triceps']::text[],ARRAY[]::text[],ARRAY['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.','Place your non lifting hand on your bicep for support.','Slowly begin to lower the dumbbell down as you breathe in.','Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).','Repeat until you have performed your set repetitions.','Switch arms and repeat the movement.']::text[]),
('one-arm-supinated-dumbbell-triceps-extension','One Arm Supinated Dumbbell Triceps Extension','triceps','dumbbell','arms',ARRAY['triceps']::text[],ARRAY[]::text[],ARRAY['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.','Place your non lifting hand on your bicep for support.','Slowly begin to lower the dumbbell down as you breathe in.','Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).','Repeat until you have performed your set repetitions.','Switch arms and repeat the movement.','Switch arms again and repeat the movement.']::text[]),
('one-half-locust','One Half Locust','stretch','other','legs',ARRAY['quads']::text[],ARRAY['abs','biceps','chest']::text[],ARRAY['Lie facedown on the floor.','Put your left hand under your left hipbone to pad your hip and pubic bone.','Bend your right knee so you can hold the foot in your right hand.','Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time.']::text[]),
('one-handed-hang','One Handed Hang','stretch','other','back',ARRAY['lats']::text[],ARRAY['biceps']::text[],ARRAY['Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides.']::text[]),
('one-knee-to-chest','One Knee To Chest','stretch','other','legs',ARRAY['glutes']::text[],ARRAY['hamstrings','lower-back']::text[],ARRAY['Start off by lying on the floor.','Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.','Gently tug that knee toward your nose.','Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.']::text[]),
('one-leg-barbell-squat','One Leg Barbell Squat','squat','barbell','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings']::text[],ARRAY['Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.','Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.','Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.','As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.','Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.','Repeat for the recommended amount of repetitions.','Switch legs and repeat the movement.']::text[]),
('open-palm-kettlebell-clean','Open Palm Kettlebell Clean','olympic-lift','other','legs',ARRAY['hamstrings']::text[],ARRAY['glutes','lower-back','quads','shoulders-front','shoulders-side']::text[],ARRAY['Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.','Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.','Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.']::text[]),
('otis-up','Otis-Up','otis-up','other','core',ARRAY['abs']::text[],ARRAY['chest','shoulders-front','shoulders-side','triceps']::text[],ARRAY['Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.','Initiate the movement by flexing the hips and spine to raise your torso up from the ground.','As you move up, press the weight up so that it is above your head at the top of the movement.','Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.']::text[]),
('overhead-cable-curl','Overhead Cable Curl','curl','cable','arms',ARRAY['biceps']::text[],ARRAY[]::text[],ARRAY['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.','Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.','Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.','While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.','While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.','Repeat for the recommended amount of repetitions prescribed in your program.']::text[]),
('overhead-lat','Overhead Lat','stretch','other','back',ARRAY['lats']::text[],ARRAY['triceps']::text[],ARRAY['Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.','Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.','After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides.']::text[]),
('overhead-slam','Overhead Slam','overhead-slam','other','back',ARRAY['lats']::text[],ARRAY[]::text[],ARRAY['Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.','Initiate the countermovement by raising the ball above your head and fully extending your body.','Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.','Receive the ball with both hands on the bounce and repeat the movement.']::text[]),
('overhead-squat','Overhead Squat','squat','barbell','legs',ARRAY['quads']::text[],ARRAY['abs','calves','glutes','hamstrings','lower-back','shoulders-front','shoulders-side','triceps']::text[],ARRAY['Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.','Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.','Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.','Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.','Now use your feet and legs to help bring the weight back up to the starting position while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
('overhead-stretch','Overhead Stretch','stretch','other','core',ARRAY['abs']::text[],ARRAY['chest','forearms','lats','triceps']::text[],ARRAY['Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.','To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso.']::text[]),
('overhead-triceps','Overhead Triceps','triceps','bodyweight','arms',ARRAY['triceps']::text[],ARRAY['lats']::text[],ARRAY['Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.','Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.','After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides.']::text[]),
('pallof-press','Pallof Press','pallof-press','cable','core',ARRAY['abs']::text[],ARRAY['chest','shoulders-front','shoulders-side','triceps']::text[],ARRAY['Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.','With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.','With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.','Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.','Hold the repetition for several seconds before returning to the starting position.','At the conclusion of the set, repeat facing the other direction.']::text[]),
('pallof-press-with-rotation','Pallof Press With Rotation','pallof-press-rotation','cable','core',ARRAY['abs']::text[],ARRAY['chest','shoulders-front','shoulders-side','triceps']::text[],ARRAY['Connect a standard handle to a tower, and position the cable to shoulder height.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.','With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.','Facing forward, press the cable away from your chest. You core should be tight and engaged.','Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.','Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.','With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
('palms-down-dumbbell-wrist-curl-over-a-bench','Palms-Down Dumbbell Wrist Curl Over A Bench','wrist-curl','dumbbell','arms',ARRAY['forearms']::text[],ARRAY[]::text[],ARRAY['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
('palms-down-wrist-curl-over-a-bench','Palms-Down Wrist Curl Over A Bench','wrist-curl','barbell','arms',ARRAY['forearms']::text[],ARRAY[]::text[],ARRAY['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
('palms-up-barbell-wrist-curl-over-a-bench','Palms-Up Barbell Wrist Curl Over A Bench','wrist-curl','barbell','arms',ARRAY['forearms']::text[],ARRAY[]::text[],ARRAY['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
('palms-up-dumbbell-wrist-curl-over-a-bench','Palms-Up Dumbbell Wrist Curl Over A Bench','wrist-curl','dumbbell','arms',ARRAY['forearms']::text[],ARRAY[]::text[],ARRAY['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
('parallel-bar-dip','Parallel Bar Dip','dips','other','arms',ARRAY['triceps']::text[],ARRAY['chest','shoulders-front','shoulders-side']::text[],ARRAY['Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.','Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.','Reverse the motion by extending the elbow, pushing yourself back up into the starting position.','Repeat for the desired number of repetitions.']::text[]),
('pelvic-tilt-into-bridge','Pelvic Tilt Into Bridge','hip-thrust','other','back',ARRAY['lower-back']::text[],ARRAY[]::text[],ARRAY['Lie down with your feet on the floor, heels directly under your knees.','Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach.','To go into a bridge, lift the entire spine except the neck.']::text[]),
('peroneals-smr','Peroneals-SMR','stretch','other','legs',ARRAY['calves']::text[],ARRAY[]::text[],ARRAY['Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.','Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg.']::text[]),
('peroneals-stretch','Peroneals Stretch','stretch','other','legs',ARRAY['calves']::text[],ARRAY[]::text[],ARRAY['In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.','With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.']::text[]),
('physioball-hip-bridge','Physioball Hip Bridge','hip-thrust','other','legs',ARRAY['glutes']::text[],ARRAY['hamstrings']::text[],ARRAY['Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.','Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.','Pause at the top of the motion and return to the starting position.']::text[]),
('pin-presses','Pin Presses','pin-presses','barbell','arms',ARRAY['triceps']::text[],ARRAY['chest','forearms','lats','upper-back','shoulders-front','shoulders-side']::text[],ARRAY['Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.','The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.','Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.','Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.','Return the bar to the pins, pausing before beginning the next repetition.']::text[]),
('piriformis-smr','Piriformis-SMR','stretch','other','legs',ARRAY['glutes']::text[],ARRAY[]::text[],ARRAY['Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.','Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.']::text[]),
('plate-pinch','Plate Pinch','plate-pinch','other','arms',ARRAY['forearms']::text[],ARRAY[]::text[],ARRAY['Grab two wide-rimmed plates and put them together with the smooth sides facing outward','Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.','Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.','Repeat for the recommended amount of sets prescribed in your program.','Switch arms and repeat the movements.']::text[]),
('plate-twist','Plate Twist','rotation','other','core',ARRAY['abs']::text[],ARRAY[]::text[],ARRAY['Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.','Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.','Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.','Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.','Repeat for the recommended amount of repetitions.']::text[]),
('platform-hamstring-slides','Platform Hamstring Slides','platform-hamstring-slides','other','legs',ARRAY['hamstrings']::text[],ARRAY['glutes']::text[],ARRAY['For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.','Begin the movement by flexing the knee, keeping your other leg straight.','Continue bringing the heel closer to you, sliding it on the floor.','At full knee flexion, reverse the movement to return to the starting position.']::text[]),
('plie-dumbbell-squat','Plie Dumbbell Squat','squat','dumbbell','legs',ARRAY['quads']::text[],ARRAY['abs','calves','glutes','hamstrings']::text[],ARRAY['Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.','Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.','Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.','Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
('plyo-kettlebell-pushups','Plyo Kettlebell Pushups','push-up','other','chest',ARRAY['chest']::text[],ARRAY['shoulders-front','shoulders-side','triceps']::text[],ARRAY['Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.','Begin by lowering yourself as low as you can, keeping your back straight.','Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.']::text[]),
('plyo-push-up','Plyo Push-up','push-up','bodyweight','chest',ARRAY['chest']::text[],ARRAY['shoulders-front','shoulders-side','triceps']::text[],ARRAY['Move into a prone position on the floor, supporting your weight on your hands and toes.','Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.','Descend by flexing at the elbow, lowering your chest towards the ground.','At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.','Return to the starting position and repeat the exercise.','For added difficulty, add claps into the movement while you are air borne.']::text[]),
('posterior-tibialis-stretch','Posterior Tibialis Stretch','stretch','other','legs',ARRAY['calves']::text[],ARRAY[]::text[],ARRAY['In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.','With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.']::text[]),
('power-clean','Power Clean','olympic-lift','barbell','legs',ARRAY['hamstrings']::text[],ARRAY['calves','forearms','glutes','lower-back','upper-back','quads','shoulders-front','shoulders-side','traps','triceps']::text[],ARRAY['Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.','Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.','Place the bar about 1 inch in front of your shins and over the balls of your feet.','Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.','Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.','Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.','Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.','As the bar raises keep it as close to the shins as possible.','As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.','Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.','Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.','Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.','When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.','As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.','Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.','After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.','Simultaneously, flex the hips and knees into a quarter squat position.','Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.','Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.','Stand up by extending the hips and knees to a fully erect position.','Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.','Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.','Squat down with the elbows fully extended until the bar touches the floor.','Start over at Phase 1 and repeat for the recommended amount of repetitions.']::text[]),
('power-clean-from-blocks','Power Clean from Blocks','olympic-lift','barbell','legs',ARRAY['hamstrings']::text[],ARRAY['quads']::text[],ARRAY['With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.','In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes.']::text[]),
('power-jerk','Power Jerk','olympic-lift','barbell','legs',ARRAY['quads']::text[],ARRAY['abs','calves','glutes','hamstrings','shoulders-front','shoulders-side','triceps']::text[],ARRAY['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.','Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.','At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.','Receive the bar with the arms locked out overhead.','Return to a standing position.']::text[]),
('power-partials','Power Partials','power-partials','dumbbell','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY[]::text[],ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.','Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.','Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.','Repeat for the recommended amount of repetitions.']::text[]),
('power-snatch','Power Snatch','olympic-lift','barbell','legs',ARRAY['hamstrings']::text[],ARRAY['calves','glutes','lower-back','quads','shoulders-front','shoulders-side','traps','triceps']::text[],ARRAY['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.','Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.','Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.','Return to a standing position with the weight over head.']::text[]),
('power-snatch-from-blocks','Power Snatch from Blocks','olympic-lift','barbell','legs',ARRAY['quads']::text[],ARRAY['calves','forearms','glutes','hamstrings','lower-back','shoulders-front','shoulders-side','traps','triceps']::text[],ARRAY['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.','Begin the first pull by driving through the front of the heels, raising the bar from the boxes.','Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.','Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.']::text[]),
('power-stairs','Power Stairs','power-stairs','other','legs',ARRAY['hamstrings']::text[],ARRAY['quads','calves','glutes','lower-back','shoulders-front','shoulders-side','traps']::text[],ARRAY['In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.','Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.','As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair.','Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible.']::text[]),
('preacher-curl','Preacher Curl','curl','barbell','arms',ARRAY['biceps']::text[],ARRAY[]::text[],ARRAY['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.','With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.','As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.','Repeat for the recommended amount of repetitions.']::text[]),
('preacher-hammer-dumbbell-curl','Preacher Hammer Dumbbell Curl','hammer-curl','dumbbell','arms',ARRAY['biceps']::text[],ARRAY['forearms']::text[],ARRAY['Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).','As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.','Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[]),
('press-sit-up','Press Sit-Up','crunch','barbell','core',ARRAY['abs']::text[],ARRAY['chest','shoulders-front','shoulders-side','triceps']::text[],ARRAY['To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.','While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.','Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.','Repeat for the recommended amount of repetitions.']::text[]),
('prone-manual-hamstring','Prone Manual Hamstring','prone-manual-hamstring','other','legs',ARRAY['hamstrings']::text[],ARRAY[]::text[],ARRAY['You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.','To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.','Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction.']::text[]),
('prowler-sprint','Prowler Sprint','cardio','other','legs',ARRAY['hamstrings']::text[],ARRAY['calves','chest','glutes','quads','shoulders-front','shoulders-side']::text[],ARRAY['Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.','You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.','With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.']::text[]),
('pull-through','Pull Through','pull-through','cable','legs',ARRAY['glutes']::text[],ARRAY['hamstrings','lower-back']::text[],ARRAY['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.','Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[]),
('push-up-wide','Push-Up Wide','push-up','bodyweight','chest',ARRAY['chest']::text[],ARRAY['abs','shoulders-front','shoulders-side','triceps']::text[],ARRAY['With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.','To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.','After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
('push-ups-close-triceps-position','Push-Ups - Close Triceps Position','push-up','bodyweight','arms',ARRAY['triceps']::text[],ARRAY['chest','shoulders-front','shoulders-side']::text[],ARRAY['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.','Lower yourself until your chest almost touches the floor as you inhale.','Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
('push-ups-with-feet-elevated','Push-Ups With Feet Elevated','push-up','bodyweight','chest',ARRAY['chest']::text[],ARRAY['shoulders-front','shoulders-side','triceps']::text[],ARRAY['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.','Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.','Lower yourself until your chest almost touches the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
('push-ups-with-feet-on-an-exercise-ball','Push-Ups With Feet On An Exercise Ball','push-up','other','chest',ARRAY['chest']::text[],ARRAY['shoulders-front','shoulders-side','triceps']::text[],ARRAY['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.','Place your toes on top of an exercise ball. This will allow your body to be elevated.','Lower yourself until your chest almost touches the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
('push-press','Push Press','shoulder-press','barbell','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['quads','triceps']::text[],ARRAY[]::text[]),
('push-press-behind-the-neck','Push Press - Behind the Neck','shoulder-press','barbell','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['calves','quads','triceps']::text[],ARRAY['Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.','Using the momentum generated, finish pressing the weight overhead be extending through the arms.','Return to the starting position, using your legs to absorb the impact.']::text[]),
('push-up-to-side-plank','Push Up to Side Plank','push-up','bodyweight','chest',ARRAY['chest']::text[],ARRAY['abs','shoulders-front','shoulders-side','triceps']::text[],ARRAY['Get into pushup position on the toes with your hands just outside of shoulder width.','Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.','Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.','Lower the arm back to the floor for another pushup and then twist to the other side.','Repeat the series, alternating each side, for 10 or more reps.']::text[]),
('pushups-close-and-wide-hand-positions','Pushups (Close and Wide Hand Positions)','push-up','bodyweight','chest',ARRAY['chest']::text[],ARRAY['shoulders-front','shoulders-side','triceps']::text[],ARRAY['Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.','Lower yourself until your chest almost touches the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
('pyramid','Pyramid','stretch','other','back',ARRAY['lower-back']::text[],ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.','Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders.']::text[]),
('quad-stretch','Quad Stretch','stretch','other','legs',ARRAY['quads']::text[],ARRAY[]::text[],ARRAY['Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.','With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.']::text[]),
('quadriceps-smr','Quadriceps-SMR','stretch','other','legs',ARRAY['quads']::text[],ARRAY[]::text[],ARRAY['Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.','Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides.']::text[]),
('quick-leap','Quick Leap','quick-leap','other','legs',ARRAY['quads']::text[],ARRAY['calves','hamstrings']::text[],ARRAY['You will need a box for this exerise.','Begin facing the box standing 1-2 feet from its edge.','By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.','Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing.']::text[]),
('rack-delivery','Rack Delivery','rack-delivery','barbell','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['forearms','traps']::text[],ARRAY['This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.','Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.','It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further.']::text[]),
('rack-pull-with-bands','Rack Pull with Bands','rack-pull-bands','barbell','back',ARRAY['lower-back']::text[],ARRAY['forearms','glutes','hamstrings','quads','traps']::text[],ARRAY['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.','Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.','With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat.']::text[]),
('rack-pulls','Rack Pulls','rack-pulls','barbell','back',ARRAY['lower-back']::text[],ARRAY['forearms','glutes','hamstrings','traps']::text[],ARRAY['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.','With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.','Return the weight to the pins and repeat.']::text[]),
('rear-leg-raises','Rear Leg Raises','rear-delt','bodyweight','legs',ARRAY['quads']::text[],ARRAY[]::text[],ARRAY['Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.','Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides.']::text[]),
('recumbent-bike','Recumbent Bike','cardio','machine','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings']::text[],ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.','Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.','Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running.']::text[]),
('return-push-from-stance','Return Push from Stance','return-push-from','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['chest','triceps']::text[],ARRAY['You will need a partner for this drill.','Begin in an athletic 2 or 3 point stance.','At the signal, move into a position to receive the pass from your partner.','Catch the medicine ball with both hands and immediately throw it back to your partner.','You can modify this drill by running different routes.']::text[]),
('reverse-band-bench-press','Reverse Band Bench Press','flat-press','barbell','arms',ARRAY['triceps']::text[],ARRAY['chest','forearms','lats','upper-back','shoulders-front','shoulders-side']::text[],ARRAY['Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.','Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.','Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
('reverse-band-box-squat','Reverse Band Box Squat','squat','barbell','legs',ARRAY['quads']::text[],ARRAY['glutes','calves','forearms','hamstrings','lower-back']::text[],ARRAY['Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[]),
('reverse-band-deadlift','Reverse Band Deadlift','deadlift','barbell','back',ARRAY['lower-back']::text[],ARRAY['glutes','quads','calves','hamstrings']::text[],ARRAY['Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.','Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.','After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
('reverse-band-power-squat','Reverse Band Power Squat','squat','barbell','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings','lower-back']::text[],ARRAY['Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.','Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.','Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[]),
('reverse-band-sumo-deadlift','Reverse Band Sumo Deadlift','deadlift','barbell','legs',ARRAY['hamstrings']::text[],ARRAY['glutes','quads','calves','forearms','lower-back','traps']::text[],ARRAY['Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.','Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.','Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
('reverse-barbell-curl','Reverse Barbell Curl','curl','barbell','arms',ARRAY['biceps']::text[],ARRAY['forearms']::text[],ARRAY['Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.','While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-barbell-preacher-curls','Reverse Barbell Preacher Curls','curl','barbell','arms',ARRAY['biceps']::text[],ARRAY['forearms']::text[],ARRAY['Grab an EZ-bar using a shoulder width and palms down (pronated) grip.','Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.','As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.','As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-cable-curl','Reverse Cable Curl','curl','cable','arms',ARRAY['biceps']::text[],ARRAY['forearms']::text[],ARRAY['Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-crunch','Reverse Crunch','crunch','bodyweight','core',ARRAY['abs']::text[],ARRAY[]::text[],ARRAY['Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.','Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.','While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.','Hold the contraction for a second and move your legs back to the starting position while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-flyes-with-external-rotation','Reverse Flyes With External Rotation','rear-delt','dumbbell','shoulders',ARRAY['shoulders-rear']::text[],ARRAY[]::text[],ARRAY['To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.','Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.','Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.','As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.','The arms should be elevated until they are level with the head.','Feel the contraction and slowly lower the weights back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-grip-bent-over-rows','Reverse Grip Bent-Over Rows','row','barbell','back',ARRAY['upper-back']::text[],ARRAY['biceps','lats','shoulders-front','shoulders-side']::text[],ARRAY['Stand erect while holding a barbell with a supinated grip (palms facing up).','Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-grip-triceps-pushdown','Reverse Grip Triceps Pushdown','triceps','cable','arms',ARRAY['triceps']::text[],ARRAY[]::text[],ARRAY['Start by setting a bar attachment (straight or e-z) on a high pulley machine.','Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.','Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.','Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-hyperextension','Reverse Hyperextension','back-extension','machine','legs',ARRAY['hamstrings']::text[],ARRAY['calves','glutes']::text[],ARRAY['Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.','To begin the movement, flex the hips, pulling the legs forward.','Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.','Return by again flexing the hip, pulling the carriage forward as far as you can.','Repeat for the desired number of repetitions.']::text[]),
('reverse-machine-flyes','Reverse Machine Flyes','fly','machine','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY[]::text[],ARRAY['Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.','In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.','Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.','Pause at the rear of the movement, and slowly return the weight to the starting position.']::text[]),
('reverse-plate-curls','Reverse Plate Curls','curl','other','arms',ARRAY['biceps']::text[],ARRAY['forearms']::text[],ARRAY['Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position.','Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.','Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.','Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling','Repeat for the recommended amount of repetitions.']::text[]),
('reverse-triceps-bench-press','Reverse Triceps Bench Press','flat-press','barbell','arms',ARRAY['triceps']::text[],ARRAY['chest','shoulders-front','shoulders-side']::text[],ARRAY['Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
('rhomboids-smr','Rhomboids-SMR','stretch','other','back',ARRAY['upper-back']::text[],ARRAY['traps']::text[],ARRAY['Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.','Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds.']::text[]),
('rickshaw-carry','Rickshaw Carry','rickshaw-carry','other','arms',ARRAY['forearms']::text[],ARRAY['abs','calves','glutes','hamstrings','lower-back','quads','traps']::text[],ARRAY['Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.','Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.']::text[]),
('rickshaw-deadlift','Rickshaw Deadlift','deadlift','other','legs',ARRAY['quads']::text[],ARRAY['forearms','glutes','hamstrings','lower-back','traps']::text[],ARRAY['Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract.','With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.','Lower the weight by bending at the hips and guiding it to the ground.']::text[]),
('ring-dips','Ring Dips','dips','other','arms',ARRAY['triceps']::text[],ARRAY['chest','shoulders-front','shoulders-side']::text[],ARRAY['Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.','Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.','Reverse the motion by extending the elbow, pushing yourself back up into the starting position.','Repeat for the desired number of repetitions.']::text[]),
('rocket-jump','Rocket Jump','rocket-jump','bodyweight','legs',ARRAY['quads']::text[],ARRAY['calves','hamstrings']::text[],ARRAY['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.','To initiate the move, squat down halfway and explode back up as high as possible.','Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.']::text[]),
('rocking-standing-calf-raise','Rocking Standing Calf Raise','calf','barbell','legs',ARRAY['calves']::text[],ARRAY[]::text[],ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.','Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.','Hold for a second and bring them back down as you breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
('rocky-pull-ups-pulldowns','Rocky Pull-Ups/Pulldowns','vertical-pull','other','back',ARRAY['lats']::text[],ARRAY['biceps','upper-back','shoulders-front','shoulders-side']::text[],ARRAY['Grab the pull-up bar with the palms facing forward using a wide grip.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.','Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program.']::text[]),
('romanian-deadlift-from-deficit','Romanian Deadlift from Deficit','hinge','barbell','legs',ARRAY['hamstrings']::text[],ARRAY['forearms','glutes','lower-back','traps']::text[],ARRAY['Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion.','Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.','Reverse the motion to return to the starting position.']::text[]),
('rope-climb','Rope Climb','rope-climb','other','back',ARRAY['lats']::text[],ARRAY['biceps','forearms','upper-back','shoulders-front','shoulders-side']::text[],ARRAY['Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.','Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.','Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.','Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.','To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion.']::text[]),
('rope-crunch','Rope Crunch','crunch','cable','core',ARRAY['abs']::text[],ARRAY[]::text[],ARRAY['Kneel 1-2 feet in front of a cable system with a rope attached.','After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.','To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.','Pause at the bottom of the motion, and then slowly return to the starting position.','These can be done with twists or to the side to hit the obliques.']::text[]),
('rope-jumping','Rope Jumping','cardio','other','legs',ARRAY['quads']::text[],ARRAY['calves','hamstrings']::text[],ARRAY['Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.','Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running.']::text[]),
('rope-straight-arm-pulldown','Rope Straight-Arm Pulldown','vertical-pull','cable','back',ARRAY['lats']::text[],ARRAY[]::text[],ARRAY['Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.','Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.','Pause at the bottom of the motion, squeezing your lats.','Return to the starting position without allowing the weight to fully rest on the stack.']::text[]),
('round-the-world-shoulder-stretch','Round The World Shoulder Stretch','stretch','other','shoulders',ARRAY['shoulders-front','shoulders-side']::text[],ARRAY['biceps','chest']::text[],ARRAY['Stand up straight with your legs together, holding a bodybar or broomstick.','Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.','Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further.']::text[]),
('rowing-stationary','Rowing, Stationary','cardio','machine','legs',ARRAY['quads']::text[],ARRAY['biceps','calves','glutes','hamstrings','lower-back','upper-back']::text[],ARRAY['To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.','There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.','The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase.']::text[]),
('runner-s-stretch','Runner''s Stretch','stretch','other','legs',ARRAY['hamstrings']::text[],ARRAY['calves']::text[],ARRAY['It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.','Keep the front heel on the floor (if it lifts up, scoot your other leg further back).','Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.']::text[]),
('running-treadmill','Running, Treadmill','cardio','machine','legs',ARRAY['quads']::text[],ARRAY['calves','glutes','hamstrings']::text[],ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.','Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[]),
('russian-twist','Russian Twist','rotation','bodyweight','core',ARRAY['abs']::text[],ARRAY['lower-back']::text[],ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.','Twist your torso to the right side until your arms are parallel with the floor while breathing out.','Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.','Repeat for the recommended amount of repetitions.']::text[]),
('sandbag-load','Sandbag Load','sandbag-load','other','legs',ARRAY['quads']::text[],ARRAY['abs','biceps','calves','forearms','glutes','hamstrings','lower-back','upper-back','shoulders-front','shoulders-side','traps']::text[],ARRAY['To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.','Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.','Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off.','Return to the starting position to retrieve the next sandbag, and repeat until the event is completed.']::text[]),
('scapular-pull-up','Scapular Pull-Up','vertical-pull','other','back',ARRAY['traps']::text[],ARRAY['lats','upper-back']::text[],ARRAY['Take a pronated grip on a pull-up bar.','From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.','Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.']::text[]),
('scissor-kick','Scissor Kick','stretch','bodyweight','core',ARRAY['abs']::text[],ARRAY[]::text[],ARRAY['To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.','With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.','Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.','Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
('scissors-jump','Scissors Jump','scissors-jump','bodyweight','legs',ARRAY['quads']::text[],ARRAY['glutes','hamstrings']::text[],ARRAY['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.','Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.','As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.','As you land, absorb the impact through the legs by adopting the lunge position, and repeat.']::text[]),
('seated-band-hamstring-curl','Seated Band Hamstring Curl','leg-curl','other','legs',ARRAY['hamstrings']::text[],ARRAY[]::text[],ARRAY['Secure a band close to the ground and place a bench a couple feet away from it.','Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.','Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.','Pause at the completion of the movement, and then slowly return to the starting position.']::text[])
) AS v(slug, name, family, equipment, muscle_group, primary_muscles, secondary_muscles, steps)
WHERE NOT EXISTS (
  SELECT 1 FROM public.exercises e
  WHERE regexp_replace(lower(e.name), '[^a-z0-9]', '', 'g') = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
)
ON CONFLICT (slug) DO NOTHING;
